verify:
choices = {o: choices[n] for o, n in {'B': 'A', 'C': 'B', 'A': 'C', 'D': 'D'}.items()}; answer = {'A': 'B', 'B': 'C', 'C': 'A', 'D': 'D'}[answer]  # shuffled: original letters
def iv(s, v):
    u = s.strip()[2:-2].replace('\\le', '<=').replace('\\ge', '>=')
    if u.startswith(v + ' '):
        return value(u).as_set()
    L, Rt = u.split(' ' + v + ' ')
    return value(L + ' ' + v).as_set() & value(v + ' ' + Rt).as_set()
n = symbols('n')
S = solve_univariate_inequality(30 + Rational(5, 2)*n >= 495, n, relational=False) & solve_univariate_inequality(30 + Rational(5, 2)*n <= 505, n, relational=False)
assert S == Interval(186, 190)
ok = [k for k in choices if iv(choices[k], 'n') == S]
assert ok == [answer]
